START TRANSACTION;

-- reglas_intro_cards
INSERT INTO convocatoria_content (torneoid, section_id, section_type, content, enabled) VALUES (346, 'reglas_intro_cards', 'cards', '[{"icon": "BookOpen", "title": "Reglas USGA / FMG", "body": "Regirán las Reglas de Golf de la USGA adoptadas por la Federación Mexicana de Golf y las Reglas Locales y Términos de la Competencia del torneo, mismas que dejan sin efecto las del club sede. Es responsabilidad de los jugadores conocer las Reglas de Golf, las Reglas Locales y los Términos de la Competencia. La penalidad por violar una Regla Local es penalidad general, salvo indicación en contrario."}, {"icon": "Scale", "title": "Sistema de Handicap", "body": "Se utiliza el hándicap registrado en FMG o en el sistema interno del club publicado al 1° de abril de 2026. Las categorías que aplican hándicap juegan al 80% de su H.I."}, {"icon": "Gavel", "title": "Comité de Reglas", "body": "Eduardo Topete Señkowski (33 3100 1191, todos los días), Gina Mendoza (55 4393 5084, jueves 30 de abril, viernes 1° y sábado 2 de mayo) y cualquier persona designada por el Comité. Las decisiones del Comité son inapelables."}]', 1)
ON DUPLICATE KEY UPDATE
  section_type = 'cards',
  content = '[{"icon": "BookOpen", "title": "Reglas USGA / FMG", "body": "Regirán las Reglas de Golf de la USGA adoptadas por la Federación Mexicana de Golf y las Reglas Locales y Términos de la Competencia del torneo, mismas que dejan sin efecto las del club sede. Es responsabilidad de los jugadores conocer las Reglas de Golf, las Reglas Locales y los Términos de la Competencia. La penalidad por violar una Regla Local es penalidad general, salvo indicación en contrario."}, {"icon": "Scale", "title": "Sistema de Handicap", "body": "Se utiliza el hándicap registrado en FMG o en el sistema interno del club publicado al 1° de abril de 2026. Las categorías que aplican hándicap juegan al 80% de su H.I."}, {"icon": "Gavel", "title": "Comité de Reglas", "body": "Eduardo Topete Señkowski (33 3100 1191, todos los días), Gina Mendoza (55 4393 5084, jueves 30 de abril, viernes 1° y sábado 2 de mayo) y cualquier persona designada por el Comité. Las decisiones del Comité son inapelables."}]',
  enabled = 1,
  updated_at = CURRENT_TIMESTAMP;

-- reglas_locales
INSERT INTO convocatoria_content (torneoid, section_id, section_type, content, enabled) VALUES (346, 'reglas_locales', 'accordion', '[{"titulo": "Reglas de juego", "contenido": "Se jugará bajo las reglas de la USGA adoptadas por la Federación Mexicana de Golf, así como las reglas locales y términos de la competencia que se publicarán para el torneo."}, {"titulo": "Resolución de controversias", "contenido": "Las controversias que se originen sobre cualquier punto relacionado con la aplicación de las reglas serán resueltas por el Oficial de Reglas y/o el Comité Organizador y su fallo será definitivo e inapelable."}, {"titulo": "Rondas estipuladas", "contenido": "Las rondas de juego estipuladas para este torneo son de 9 hoyos."}, {"titulo": "Marcas de salida — Damas", "contenido": "Categorías A, B, C, D y E: marcas Rojas. Estelares: marcas Naranjas."}, {"titulo": "Marcas de salida — Caballeros", "contenido": "Campeonato: marcas Negras. Premier y AA: marcas Azules. A, B, C y D: marcas Blancas."}, {"titulo": "Marcas de salida — Seniors", "contenido": "Campeonato Mayores: marcas Blancas. A y B: marcas Doradas."}, {"titulo": "Horarios de salida", "contenido": "Las salidas del turno matutino serán a partir de las 06:10 hrs. Las salidas del turno vespertino serán a partir de las 11:00 hrs."}, {"titulo": "Cuestiones climatológicas", "contenido": "Si por cuestiones climatológicas no se logran jugar dos rondas de 18 hoyos, el comité organizador decidirá a cuántos hoyos se hará el corte."}, {"titulo": "Cupos por categoría", "contenido": "Si una categoría alcanza el número máximo de jugadores, se cerrará y los jugadores que queden fuera entrarán a una lista de espera. Si hay alguna cancelación o espacio disponible, se llamará al jugador para que pueda inscribirse y forme parte del field del torneo."}, {"titulo": "1. Fuera de límites", "contenido": "Señalado por estacas y líneas blancas, bardas y contornos de caminos así señalados. El fuera de límites del lado izquierdo del Hoyo 2 se aplica únicamente al juego del Hoyo 2."}, {"titulo": "2. Objetos integrales (sin alivio sin penalidad)", "contenido": "Muros de contención de lagos, ríos, canales y plataformas de salida; jardineras y plantas de ornato no marcadas como terreno en reparación ni como obstrucciones; cajetes de los árboles; cualquier objeto unido a un árbol, esté atado o no. También los liners (plástico) debajo de la arena en bunkers y del mulch alrededor de los árboles (no hay alivio sin penalidad de estos liners/plástico).\\n\\nExcepción: los muros de contención de las áreas de salida de los Hoyos 11 y 13 NO son objetos integrales; son obstrucciones inamovibles (alivio sin penalidad según la Regla 16.1b)."}, {"titulo": "3. Áreas de penalidad rojas", "contenido": "Identificadas con estacas y/o líneas rojas. Existen círculos de dropeo adicionales y opcionales en los Hoyos 3 y 4; si el jugador decide dropear en un círculo, deberá hacerlo en el que corresponda de acuerdo a las líneas blancas que así lo indican."}, {"titulo": "4. Condiciones anormales del campo (alivio sin penalidad)", "contenido": "Terreno en Reparación:\\n• Áreas identificadas con líneas blancas o estacas azules.\\n• Zona Prohibida Para Jugar — alivio obligatorio sin penalidad (dropear dentro del largo de un bastón del punto de alivio completo más cercano sin acercarse al hoyo):\\n   o El vivero (línea blanca) entre los Hoyos 12, 13 y 14.\\n   o El vivero (línea blanca) entre los Hoyos 5 y 13.\\n• Ranuras alrededor de los greenes: en efecto el MRL F-19. El alivio sólo aplica si la bola reposa sobre la ranura (dropear dentro de un bastón del punto de alivio más cercano y no en green). No hay alivio por interferencia de la ranura por swing, stance o línea de juego.\\n• Los tensores que sostienen algunos árboles son obstrucciones.\\n• En los Hoyos 12 y 18, los nuevos bunkers de fairway están en juego: si una bola reposa en ellos se juega desde ahí o se toma alivio con penalidad. Las áreas marcadas fuera y junto a estos bunkers son terreno en reparación, con alivio sin penalidad según la Regla 16.1b.\\n\\nObstrucciones inamovibles:\\n• Hoyo 6: el snack, el kiosko y las jardineras son una sola obstrucción. Si el jugador decide dropear en un círculo, deberá usar el que corresponda al hoyo que se esté jugando.\\n• El área de la pizarra de yardaje definida con liner de plástico en la salida de cada hoyo.\\n• El área de máquinas en el Hoyo 14, con un círculo de dropeo como opción adicional de alivio.\\n• Cuando una obstrucción inamovible se junta con otra condición anormal del campo, se considera una sola al tomar alivio bajo la Regla 16.1 (MRL 8F-3 en efecto).\\n• Las jardineras circundadas por caminos se consideran parte del camino.\\n• Los muros de contención al lado izquierdo del Hoyo 1, en las mesas de salida de los Hoyos 11 y 13, y atrás del green del Hoyo 16.\\n\\nObstrucciones inamovibles cerca del green (MRL 8F-5): alivio bajo la Regla 16.1. Adicionalmente, si la bola reposa en el área general y una obstrucción inamovible dentro del largo de dos bastones del green —y dentro de dos bastones de la bola— interviene con la línea de juego, el jugador puede dropear dentro de un bastón del punto más cercano de alivio completo que (a) no se acerque al hoyo, (b) evite la intervención, y (c) no esté en un área de penalidad ni en un green.\\n\\nObstrucciones temporales inamovibles (TIO''s, MRL 8F-23): carpas de promoción y recepción de scores, automóviles de exhibición dentro o fuera del campo, anuncios publicitarios, cámaras de video en los greenes de los pares 3 y cualquier otra obstrucción que esté temporalmente en el campo y no pueda removerse con facilidad. Alivio a ambos lados de la obstrucción bajo la Regla correspondiente."}, {"titulo": "5. Uniones de pasto recién plantado (MRL 8F-7)", "contenido": "Si la bola reposa en una unión de pasto recién plantado, el jugador puede dropear sin penalidad dentro del largo de un bastón del punto de alivio completo más cercano sin acercarse al hoyo. Todas las uniones de pasto se consideran la misma para efectos del alivio. No hay alivio por interferencia sólo por el stance."}, {"titulo": "6. Zonas de dropeo", "contenido": "Son una opción adicional a la Regla aplicable. Además de los mencionados, existen dos círculos de dropeo en el Hoyo 4 como opción adicional para una bola injugable en la jardinera atrás del green que colinda con la barda de fuera de límites. Si una bola reposa en esa jardinera, el jugador puede, sin penalidad, tomar alivio según la Regla 16.1b o utilizar uno de los círculos (el más cercano)."}, {"titulo": "7. Bastones dañados (MRL 8F G-9)", "contenido": "La Regla 4.1b(3) se modifica: el jugador podrá reemplazar un bastón dañado sólo si se quebró o se dañó significativamente durante la ronda por él o su caddie, excepto que haya sido quebrado o dañado por abuso."}, {"titulo": "8. Equipos para medir distancia", "contenido": "Permitidos. Otras funciones como medir velocidad del viento, slope, etc., NO deben utilizarse (ver Regla 4.3a)."}, {"titulo": "9. Teléfonos celulares", "contenido": "Se permite su uso siempre que sea con discreción, sin retrasar el juego y sin distraer a los demás jugadores. En caso contrario, el jugador podrá ser penalizado de acuerdo con la Regla 4.3."}, {"titulo": "10. Música", "contenido": "Durante cualquier ronda está prohibido escuchar música. Primera infracción: amonestación. Segunda infracción: penalidad general. Tercera infracción: descalificación."}, {"titulo": "11. Política de ritmo de juego", "contenido": "Los jugadores deben jugar al ritmo establecido por el Comité, indicado en cada tarjeta de score (4 hrs 40 min en 18 hoyos). Si un grupo está arriba del tiempo establecido y fuera de posición, los jugadores serán cronometrados con un máximo de 40 segundos para ejecutar su golpe. Penalidad: 1er mal tiempo, un golpe de castigo; 2do mal tiempo, penalidad general; 3er mal tiempo, descalificación."}, {"titulo": "12. Cierre de la competencia", "contenido": "Se considera cerrada la competencia al iniciar la ceremonia de premiación."}, {"titulo": "Importante — líneas verdes", "contenido": "Las líneas verdes en el campo NO TIENEN NINGÚN SIGNIFICADO."}, {"titulo": "Vigencia del documento", "contenido": "Estas Reglas Locales y Términos de la Competencia dejan sin efecto cualquier regla local o término de competencia que el club utiliza para el juego normal de sus socios, se encuentren o no publicadas en cualquier parte. Cualquier versión anterior de este documento (24 de abril de 2026) queda sin efecto."}]', 1)
ON DUPLICATE KEY UPDATE
  section_type = 'accordion',
  content = '[{"titulo": "Reglas de juego", "contenido": "Se jugará bajo las reglas de la USGA adoptadas por la Federación Mexicana de Golf, así como las reglas locales y términos de la competencia que se publicarán para el torneo."}, {"titulo": "Resolución de controversias", "contenido": "Las controversias que se originen sobre cualquier punto relacionado con la aplicación de las reglas serán resueltas por el Oficial de Reglas y/o el Comité Organizador y su fallo será definitivo e inapelable."}, {"titulo": "Rondas estipuladas", "contenido": "Las rondas de juego estipuladas para este torneo son de 9 hoyos."}, {"titulo": "Marcas de salida — Damas", "contenido": "Categorías A, B, C, D y E: marcas Rojas. Estelares: marcas Naranjas."}, {"titulo": "Marcas de salida — Caballeros", "contenido": "Campeonato: marcas Negras. Premier y AA: marcas Azules. A, B, C y D: marcas Blancas."}, {"titulo": "Marcas de salida — Seniors", "contenido": "Campeonato Mayores: marcas Blancas. A y B: marcas Doradas."}, {"titulo": "Horarios de salida", "contenido": "Las salidas del turno matutino serán a partir de las 06:10 hrs. Las salidas del turno vespertino serán a partir de las 11:00 hrs."}, {"titulo": "Cuestiones climatológicas", "contenido": "Si por cuestiones climatológicas no se logran jugar dos rondas de 18 hoyos, el comité organizador decidirá a cuántos hoyos se hará el corte."}, {"titulo": "Cupos por categoría", "contenido": "Si una categoría alcanza el número máximo de jugadores, se cerrará y los jugadores que queden fuera entrarán a una lista de espera. Si hay alguna cancelación o espacio disponible, se llamará al jugador para que pueda inscribirse y forme parte del field del torneo."}, {"titulo": "1. Fuera de límites", "contenido": "Señalado por estacas y líneas blancas, bardas y contornos de caminos así señalados. El fuera de límites del lado izquierdo del Hoyo 2 se aplica únicamente al juego del Hoyo 2."}, {"titulo": "2. Objetos integrales (sin alivio sin penalidad)", "contenido"