-- reglamento_local
INSERT INTO convocatoria_content (torneoid, section_id, section_type, content, enabled) VALUES (346, 'reglamento_local', 'accordion', '[{"titulo": "Caballeros — Campeonato, Premier y AA", "contenido": "Stroke Play sin hándicap. Jugarán a 54 hoyos. Habrá corte a los 36 hoyos jugados. Pasarán a la final los mejores 12 jugadores sin empates. Cupo limitado a 36 jugadores por categoría."}, {"titulo": "Caballeros — Categoría A", "contenido": "Stroke Play sin hándicap. Edad 18 o más. Jugarán a 72 hoyos. Habrá 2 cortes: el primero a los 36 hoyos pasando los mejores 24 sin empates, y el segundo a 54 hoyos pasando a la final los primeros 12 sin empates. Cupo limitado a 80 jugadores."}, {"titulo": "Caballeros — Categorías B, C y D", "contenido": "Stableford acumulado al 80% del hándicap. Edad 18 o más. Jugarán a 72 hoyos. Habrá 2 cortes: el primero a los 36 hoyos pasando los mejores 24 sin empates y el segundo a 54 hoyos pasando a la final los primeros 12 sin empates. Cupos: B y C 96 jugadores, D 80 jugadores."}, {"titulo": "Seniors — Campeonato Mayores", "contenido": "Stroke Play al 80% del hándicap. 54 hoyos. Corte a los 36 hoyos. Pasan los mejores 4 Gross y los mejores 4 Neto a la final sin empates. Deberán tener 50 años cumplidos al primer día de juego. Juegan de marcas blancas con su hándicap. Si un jugador gana la final Gross y también la Neto, sólo recibirá el trofeo Gross. Cupo limitado a 16 jugadores."}, {"titulo": "Seniors — A y B", "contenido": "Stableford al 80% del hándicap. 54 hoyos. Corte a los 36 hoyos. Pasan los mejores 12 de cada categoría sin empates a la final conservando el acumulado. Deberán tener 60 años cumplidos al primer día de juego. Marcas doradas. Cupo límite A+B: 56 jugadores."}, {"titulo": "Damas — A y B", "contenido": "Stroke Play al 80% del hándicap. 54 hoyos. Corte a los 36 hoyos. Pasan las mejores 4 Gross y las mejores 4 Neto sin empates a la final. Si una jugadora pasa a la final Gross y también a la Neto, sólo jugará por el trofeo Gross; en ese caso la quinta mejor jugadora (Neto) jugará por el trofeo Neto."}, {"titulo": "Damas — C, D y E", "contenido": "Stableford al 80% del hándicap. 54 hoyos. Corte a los 36 hoyos. Pasan las 8 mejores jugadoras sin empates a la final conservando el acumulado de puntos. Cupo limitado entre A, B, C, D y E: 100 jugadoras."}, {"titulo": "Damas Estelares", "contenido": "27 hoyos sin hándicap. Corte a los 18 hoyos. Pasan las 6 mejores sin empates a la ronda final conservando el acumulado. Cupo límite: 12 jugadoras."}, {"titulo": "Rangos de hándicap — Caballeros", "contenido": "Campeonato: hasta 0.9 · Premier: 1.0 a 3.9 · AA: 4.0 a 7.0 · A: 7.1 a 11.3 · B: 11.4 a 15.8 · C: 15.9 a 21.2 · D: 21.3 a 28.4."}, {"titulo": "Rangos de hándicap — Seniors", "contenido": "Campeonato Mayores: hasta 9.5 · A / B: 0 a 34.6 (A y B se dividirán entre los inscritos en base al H.I.)."}, {"titulo": "Rangos de hándicap — Damas", "contenido": "A: hasta 13.5 · B: 13.6 a 17.9 · C: 18.0 a 22.3 · D: 22.4 a 27.6 · E: 27.7 a 35.5 · Estelares: sin H.C.P."}, {"titulo": "Marcas de salida — resumen oficial", "contenido": "Campeonato: Negras. Premier y AA: Azules. A, B, C, D y Campeonato Mayores: Blancas. Damas: Rojas. Damas Estelares: Naranjas."}, {"titulo": "Hora de salida", "contenido": "Tanto en Stroke Play como en Stableford, los jugadores deberán estar en su mesa de salida listos para jugar a la hora estipulada, sin importar el orden en que les toque salir. Si el jugador se presenta hasta con cinco minutos de retraso, tendrá 2 golpes de penalidad en el primer hoyo. Después de esos 5 minutos será descalificado."}, {"titulo": "Ronda estipulada", "contenido": "9 hoyos."}, {"titulo": "Vestimenta", "contenido": "Según el código interno del Reglamento de Golf del club."}, {"titulo": "Transportación automotriz", "contenido": "Los jugadores pueden utilizar transportación automotriz para ellos mismos, su equipo y su caddie."}, {"titulo": "Caddie", "contenido": "Es obligatorio para todos los jugadores contratar los servicios de un caddie (siempre y cuando el club pueda proporcionarlo), el cual puede ser compartido con otro jugador."}, {"titulo": "Puntuación Stableford", "contenido": "• 2 golpes más que el par (doble bogey): sin puntos\\n• 1 golpe más que el par (bogey): 1 punto\\n• Par: 2 puntos\\n• 1 golpe menos que par (birdie): 3 puntos\\n• 2 golpes menos que par (águila): 4 puntos\\n• 3 golpes menos que par (albatros): 5 puntos"}, {"titulo": "Suspensión de juego", "contenido": "• Suspensión inmediata del juego: una nota prolongada de sirena.\\n• Suspensión del juego: tres notas consecutivas de sirena.\\n• Reanudación del juego: dos notas consecutivas de sirena.\\n\\nCuando el juego sea suspendido por el Comité por una situación peligrosa (una nota prolongada), todos los jugadores deben SUSPENDER DE INMEDIATO su juego. Si un jugador no lo hace, será DESCALIFICADO."}, {"titulo": "Entrega de scores", "contenido": "Es responsabilidad del jugador que su tarjeta sea entregada. Debe entregarse en un lapso no mayor a 15 minutos a partir del momento en que el grupo terminó de jugar el último hoyo de la ronda, en la mesa de recepción junto a la caseta del starter. Si el jugador no entrega su tarjeta en el tiempo indicado, será descalificado."}, {"titulo": "Desempates para el corte", "contenido": "Primer criterio: mejor score de la última ronda. Si persiste el empate, se comparan los hoyos del 10 al 18 de la última ronda, continuando con los hoyos del 13 al 18, 16 al 18 y por último el hoyo 18. Si aún persiste, se hace lo mismo con los hoyos del 1 al 9."}, {"titulo": "Desempates para trofeos", "contenido": "Sólo para el primer lugar de todas las categorías Gross o Neto se jugará a muerte súbita SIN VENTAJAS (si por oscuridad o mal clima no se puede iniciar o continuar, el desempate se llevará a cabo igual que para el corte). El resto de los empates se define con los mismos criterios que para el corte. Cualquier empate en el campo iniciará a la hora y por el hoyo establecidos por el Comité."}, {"titulo": "Premios de O''Yes por día", "contenido": "Un jugador no podrá ganar más de un O''Yes por día."}, {"titulo": "Nota importante sobre el corte", "contenido": "El jugador que no pasó el corte, una vez publicadas las listas de resultados, no podrá participar en la ronda final por ningún motivo. En el caso de jugadores participando en dos categorías que pasen el corte en ambas, deberán dar aviso aclarando cuál de las dos categorías quieren jugar para la ronda final."}, {"titulo": "Cierre de la competencia", "contenido": "Al iniciarse la ceremonia de premiación."}]', 1)
ON DUPLICATE KEY UPDATE
