-- codigo_conducta
INSERT INTO convocatoria_content (torneoid, section_id, section_type, content, enabled) VALUES (346, 'codigo_conducta', 'accordion', '[{"icon": "Clock", "titulo": "Puntualidad", "contenido": "Los jugadores deberán presentarse en su hoyo de salida 5 minutos antes de la hora programada y estar listos para jugar a la hora estipulada. Si el jugador se presenta hasta con cinco minutos de retraso a su mesa de salida, tendrá 2 golpes de penalidad en el primer hoyo. Después de estos 5 minutos será descalificado."}, {"icon": "AlertTriangle", "titulo": "Ritmo de Juego", "contenido": "El tiempo máximo para completar 18 hoyos será de 4 horas y 40 minutos. Los grupos fuera de posición serán cronometrados con un máximo de 40 segundos por golpe. Penalidad: 1er mal tiempo, un golpe de castigo; 2do mal tiempo, penalidad general; 3er mal tiempo, descalificación."}, {"icon": "ScrollText", "titulo": "Código de Vestimenta", "contenido": "Vestimenta según el código interno del Reglamento de Golf del club: playera con cuello, pantalón o bermuda de vestir, y zapatos de golf. No se permiten jeans, playeras sin cuello o sandalias."}, {"icon": "Gavel", "titulo": "Dispositivos Electrónicos y Música", "contenido": "Se permite el uso de dispositivos de medición de distancia. Queda prohibido utilizar funciones que midan velocidad del viento, slope u otros parámetros (Regla 4.3a). El uso de teléfonos celulares está permitido siempre que sea con discreción, sin retrasar el juego ni distraer a los demás jugadores. Durante la ronda está prohibido escuchar música (1ª infracción: amonestación; 2ª: penalidad general; 3ª: descalificación)."}, {"icon": "BookOpen", "titulo": "Transportación y Caddie", "contenido": "Los jugadores podrán utilizar transportación automotriz para ellos mismos, su equipo y su caddie. Es obligatorio contratar los servicios de un caddie (siempre y cuando el club pueda proporcionarlo), el cual puede ser compartido con otro jugador."}, {"icon": "Scale", "titulo": "Conducta Deportiva", "contenido": "Se espera que todos los participantes mantengan una conducta deportiva ejemplar. Cualquier comportamiento antideportivo será sancionado y puede resultar en descalificación. El Comité Organizador se reserva el derecho de hacer cualquier cambio que juzgue necesario para el mejor desarrollo del torneo y cualquier punto no previsto en la presente convocatoria, o que no esté redactado con claridad, será resuelto por el Comité Organizador y su decisión será inapelable."}, {"icon": "BookOpen", "titulo": "Recomendaciones para el jugador", "contenido": "• Marcar la bola antes de levantarla para identificarla (penalidad: 1 golpe si no se marca).\\n• No hay ''dadas'': se debe embocar en todos los hoyos. En Stableford deberá embocarse toda bola que cuente para obtener puntos; de lo contrario podrá ser levantada sin embocar.\\n• No se debe cambiar bola en green (penalidad: 1 golpe).\\n• Máximo 14 bastones.\\n• No se puede dar ni pedir consejo.\\n• Presentarse en su hoyo de salida 5 minutos antes."}, {"icon": "AlertTriangle", "titulo": "Suspensión de juego — señales", "contenido": "• Suspensión inmediata (situación peligrosa): una nota prolongada de sirena — todos deben SUSPENDER DE INMEDIATO el juego o serán DESCALIFICADOS.\\n• Suspensión del juego: tres notas consecutivas de sirena.\\n• Reanudación del juego: dos notas consecutivas de sirena."}, {"icon": "Clock", "titulo": "Entrega de tarjeta de score", "contenido": "Es responsabilidad del jugador entregar su tarjeta en un máximo de 15 minutos después de que el grupo termine el último hoyo de la ronda, en la mesa de recepción junto a la caseta del starter. No entregarla a tiempo es causa de descalificación."}]', 1)
ON DUPLICATE KEY UPDATE
